def create_db():
    # 1. Δημιουργία ή Σύνδεση με τη βάση δεδομένων
    conn = sqlite3.connect('machineQuestioning.db')
    cursor = conn.cursor()

    # 2. Δημιουργία του πίνακα (Αν υπάρχει ήδη, τον σβήνουμε για να έχουμε καθαρή αρχή)
    cursor.execute('DROP TABLE IF EXISTS questions')
    cursor.execute('''
        CREATE TABLE questions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            chapter TEXT NOT NULL,
            question TEXT NOT NULL,
            option_1 TEXT NOT NULL,
            option_2 TEXT NOT NULL,
            option_3 TEXT NOT NULL,
            option_4 TEXT NOT NULL,
            correct_index INTEGER NOT NULL,
            explanation TEXT NOT NULL
        )
    ''')

    # 3. Εισαγωγή όλων των ερωτήσεων
    for q in QUESTIONS:
        cursor.execute('''
            INSERT INTO questions (chapter, question, option_1, option_2, option_3, option_4, correct_index, explanation)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        ''', (
            q['chapter'], 
            q['question'], 
            q['options'][0], 
            q['options'][1], 
            q['options'][2], 
            q['options'][3], 
            q['correct_index'], 
            q['explanation']
        ))

    # 4. Αποθήκευση και κλείσιμο
    conn.commit()
    conn.close()
    print("Η βάση δεδομένων 'machineQuestioning.db' δημιουργήθηκε επιτυχώς!")

if __name__ == '__main__':
    create_db()